// Frame extraction and lighting happen once; gameplay draws cached cutouts, not
// a brightness filter over the entire animation sheet on every frame.
export class SpriteActor {
  constructor(images){this.frames={};this.cache=new Map();for(let[type,image]of Object.entries(images))this.frames[type]=this.extract(image,type==='idle'?4:4,type==='idle'?2:8);}
  extract(image,cols,rows){const cellW=Math.ceil(image.width/cols),cellH=Math.ceil(image.height/rows),read=document.createElement('canvas');read.width=cellW;read.height=cellH;const c=read.getContext('2d',{willReadFrequently:true}),out=[];for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){c.clearRect(0,0,cellW,cellH);c.drawImage(image,col*image.width/cols,row*image.height/rows,image.width/cols,image.height/rows,0,0,cellW,cellH);let data=c.getImageData(0,0,cellW,cellH).data,x0=cellW,y0=cellH,x1=0,y1=0;for(let y=0;y<cellH;y++)for(let x=0;x<cellW;x++)if(data[(y*cellW+x)*4+3]>110){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}if(x1<=x0||y1<=y0){x0=0;y0=0;x1=cellW-1;y1=cellH-1;}let pad=3;x0=Math.max(0,x0-pad);y0=Math.max(0,y0-pad);x1=Math.min(cellW-1,x1+pad);y1=Math.min(cellH-1,y1+pad);const frame=document.createElement('canvas');frame.width=x1-x0+1;frame.height=y1-y0+1;frame.getContext('2d').drawImage(read,x0,y0,frame.width,frame.height,0,0,frame.width,frame.height);out.push({image:frame,footX:(cellW*.5-x0)/frame.width,footY:(y1-2-y0)/frame.height});}return out;}
  pose(player){const direction=((Math.round(player.facing/(Math.PI/4))%8)+8)%8,type=player.moving?(player.running?'run':'walk'):'idle',index=type==='idle'?direction:direction*4+(Math.floor(player.phase*4)%4);return{type,index,frame:this.frames[type][index]};}
  lit(type,index,tone){const key=type+':'+index+':'+tone;if(this.cache.has(key))return this.cache.get(key);let frame=this.frames[type][index],c=document.createElement('canvas');c.width=frame.image.width;c.height=frame.image.height;let x=c.getContext('2d');x.filter='brightness(1.04) contrast(1.05) saturate(.82)';x.drawImage(frame.image,0,0);x.filter='none';x.globalCompositeOperation='source-atop';x.fillStyle=tone==='warm'?'rgba(231,159,89,.15)':tone==='cool'?'rgba(85,171,188,.16)':tone==='shadow'?'rgba(5,12,20,.26)':'rgba(85,98,112,.07)';x.fillRect(0,0,c.width,c.height);this.cache.set(key,c);return c;}
  draw(ctx,player,x,y,height,tone,time,{reflection=false}={}){const{type,index,frame}=this.pose(player),image=this.lit(type,index,tone),breath=player.moving?1:1+Math.sin(time*1.5)*.003,h=height*breath*(type==='run'?.96:1),w=h*image.width/image.height;ctx.save();if(reflection){ctx.translate(x,y);ctx.scale(1,-.23);ctx.globalAlpha=.07;ctx.drawImage(image,-w*frame.footX,-h*frame.footY,w,h);}else ctx.drawImage(image,x-w*frame.footX,y-h*frame.footY,w,h);ctx.restore();}
}
export function turnToward(current,target,dt){let delta=((target-current+Math.PI*3)%(Math.PI*2))-Math.PI;return current+Math.sign(delta)*Math.min(Math.abs(delta),dt*9);}
